class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        senators = list(senate)
        counts = {"R": senate.count("R"), "D": senate.count("D")}
        bans = {"R": 0, "D": 0}
        i = 0
        while counts["R"] and counts["D"]:
            party = senators[i]
            if bans[party] > 0:
                bans[party] -= 1
                counts[party] -= 1
                senators.pop(i)
                if senators:
                    i %= len(senators)
            else:
                other = "D" if party == "R" else "R"
                bans[other] += 1
                i = (i + 1) % len(senators)
        return "Radiant" if counts["R"] else "Dire"

solutions.better:
class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        current = senate
        balance = 0
        while "R" in current and "D" in current:
            nxt = []
            for party in current:
                if party == "R":
                    if balance >= 0:
                        nxt.append("R")
                    balance += 1
                else:
                    if balance <= 0:
                        nxt.append("D")
                    balance -= 1
            current = "".join(nxt)
        return "Radiant" if current and current[0] == "R" else "Dire"

solutions.optimal:
class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        from collections import deque

        n = len(senate)
        radiant = deque(i for i, c in enumerate(senate) if c == "R")
        dire = deque(i for i, c in enumerate(senate) if c == "D")
        while radiant and dire:
            r = radiant.popleft()
            d = dire.popleft()
            if r < d:
                radiant.append(r + n)
            else:
                dire.append(d + n)
        return "Radiant" if radiant else "Dire"

